import{analyzeDataset}from'./pipeline.js';import{fmt}from'./stats.js';
// Pure service boundary for a future scheduler. No accounts, network, timers, or notifications.
export function generateClubReport(rows,{quality=null,previous=null,generatedAt=new Date().toISOString(),demo=false}={}){const s=analyzeDataset(rows,{quality}),a=s.outputs.calculate_attendance_metrics,t=s.outputs.calculate_attendance_trend,r=s.outputs.calculate_retention,h=s.outputs.generate_club_health_summary;const fingerprint=JSON.stringify(rows.map(x=>[x.date,x.attendance,x.type,x.time,x.promotion,x.reach,x.signups,x.members,x.new_members,x.returning_members,x.days_promoted_before,x.topic,x.notes,x.special_event]));const changes=previous?{changed:previous.fingerprint!==fingerprint,previousMeetings:previous.meetings,currentMeetings:rows.length}:null;const text=['# ClubPulse Health Report',`Generated: ${generatedAt}`,demo?'Fictional demo data.':'Current session dataset.',`Meetings: ${rows.length}`,`Average attendance: ${fmt(a.average)}`,t.available?`Attendance momentum: ${fmt(t.percentChange)}% (${t.label})`:'Attendance momentum: not enough comparable history.',r?.available&&r.rate!=null?`Newcomer return rate: ${fmt(r.rate*100)}% (${r.returned}/${r.eligible} eligible newcomers).`:'Cohort retention unavailable; complete member IDs and follow-up meetings are needed.','',...h.components.map(c=>`${c.name}: ${c.label}. ${c.definition}`),'','## What to try',...s.outputs.recommend_next_steps.recommendations.map(r=>`${r.title}\nEvidence: ${r.evidence}\nReason: ${r.reason}\nConfidence: ${r.confidence.level}`),'','## Data quality',...s.quality.warnings,'','Observational associations are not causal findings. Forecast ranges are empirical planning aids, not guarantees.'].join('\n\n');return{generatedAt,meetings:rows.length,fingerprint,changes,text,snapshot:s}}
